const icon=n=>'<svg viewBox="0 0 24 24" aria-hidden="true">'+(icons[n]||icons.chat)+'</svg>';
const people={me:{name:'Михаил',initials:'МВ',role:'Вы',color:'my-avatar'},anna:{name:'Анна К.',initials:'АК',role:'Менеджер',color:'lilac'},ilya:{name:'Илья С.',initials:'ИС',role:'Печатник',color:'blue'},lena:{name:'Елена Д.',initials:'ЕД',role:'Дизайнер',color:'green'}};
function timeBefore(minutes){return new Date(Date.now()-minutes*60000).toISOString()}
function seed(){return {version:1,role:'executor',active:'general',orders:[
{id:'o1',roomId:'r1',number:'ПЦ-1048',title:'Буклеты для выставки',customer:'Демо-заказчик «Маяк»',quantity:'1 000 экз.',paper:'Мелованная, 170 г/м²',format:'А5, два сгиба',due:'Сегодня, до 18:00',stage:'Печать',payment:'Не подтверждена',executorId:'me'},
{id:'o2',roomId:'r2',number:'ПЦ-1049',title:'Визитки для студии',customer:'Демо-заказчик «Форма»',quantity:'500 экз.',paper:'Дизайнерская, 300 г/м²',format:'90 × 50 мм',due:'Завтра, до 14:00',stage:'Допечатная подготовка',payment:'Не подтверждена',executorId:'lena'},
{id:'o3',roomId:'r3',number:'ПЦ-1050',title:'Каталог продукции',customer:'Демо-заказчик «Контур»',quantity:'200 экз.',paper:'Мелованная, 130 г/м²',format:'А4, 24 полосы',due:'23 октября, до 16:00',stage:'Постпечатная обработка',payment:'Не подтверждена',executorId:'me'}],
rooms:[{id:'general',name:'Общий',kind:'channel',description:'Всё важное для команды',unread:0,pinned:'В этом чате — общие вопросы и новости. Макеты и детали производства обсуждаем в чатах заказов.'},
{id:'production',name:'Производство',kind:'channel',description:'План загрузки и смены',unread:2},
{id:'design',name:'Дизайн',kind:'channel',description:'Макеты и допечатная подготовка',unread:1},
{id:'r1',name:'Буклеты для выставки',kind:'order',orderId:'o1',unread:2},
{id:'r2',name:'Визитки для студии',kind:'order',orderId:'o2',unread:0},
{id:'r3',name:'Каталог продукции',kind:'order',orderId:'o3',unread:1}],
messages:[
{id:'m1',roomId:'general',author:'anna',text:'Коллеги, доброе утро! На сегодня три заказа в работе. Давайте держать все договорённости здесь — так ничего не потеряется.',time:timeBefore(62),reactions:[]},
{id:'m2',roomId:'general',author:'ilya',text:'Доброе! Бумага для буклетов уже на участке. После приладки начнём печать.',time:timeBefore(58),reactions:['me']},
{id:'m3',roomId:'general',author:'lena',text:'Подготовила памятку по передаче макетов в печать. Перед отправкой проверяем вылеты, шрифты и цветовую модель.',time:timeBefore(51),reactions:[],attachmentDemo:true},
{id:'m4',roomId:'general',author:'anna',text:'По буклетам всё согласовано. Вопросы по цветопробе и готовности пишем в чат заказа 👇',time:timeBefore(44),orderRef:'o1',reactions:[]},
{id:'m5',roomId:'general',author:'me',text:'Принято! Возьму буклеты в работу. По готовности обновлю этап в карточке заказа.',time:timeBefore(37),reactions:[]},
{id:'m6',roomId:'r1',author:'anna',text:'Заказ согласован. Нужно 1 000 буклетов к выставке. Макет утверждён, передаю в производство.',time:timeBefore(90),reactions:[]},
{id:'m7',roomId:'r1',author:'ilya',text:'Бумага на месте. Проверяем цветопробу, затем запускаем тираж.',time:timeBefore(40),reactions:[]},
{id:'m8',roomId:'r2',author:'lena',text:'Проверяю макет визиток. Осталось уточнить вылеты и подготовить файл для печати.',time:timeBefore(50),reactions:[]},
{id:'m9',roomId:'r3',author:'ilya',text:'Печать завершена, каталог на сборке. Сообщу, когда можно будет передать на упаковку.',time:timeBefore(20),reactions:[]},
{id:'m10',roomId:'production',author:'ilya',text:'Сегодня начинаем с буклетов, затем каталог. Об изменении очереди пишите здесь.',time:timeBefore(55),reactions:[]},
{id:'m11',roomId:'design',author:'lena',text:'Чат допечатной подготовки: здесь сверяем технические требования и обсуждаем макеты.',time:timeBefore(70),reactions:[]}
]}}
const storageKey='policentr-messenger-v1';
let state;
try{state=JSON.parse(localStorage.getItem(storageKey));if(state?.version!==1||!Array.isArray(state.rooms)||!Array.isArray(state.messages)||!Array.isArray(state.orders))state=seed()}catch{state=seed()}
if(!['executor','manager'].includes(state.role))state.role='executor';
if(!state.rooms.some(r=>r.id===state.active))state.active='general';
let view='chat',query='',chatQuery='',showSearch=false,showContext=window.matchMedia('(min-width:1231px)').matches,navOpen=false,replyTo=null,pending=[],emojiOpen=false,toastTimeout;
const drafts=new Map();
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>$('#toast').classList.remove('show'),3600)}
function persist(){try{localStorage.setItem(storageKey,JSON.stringify(state));return true}catch{toast('Не удалось сохранить изменения. Экспортируйте переписку; хранилище браузера может быть заполнено.');return false}}
function activeRoom(){return state.rooms.find(r=>r.id===state.active)||state.rooms[0]}
function avatar(id,extra=''){const p=people[id]||people.me;return '<div class="avatar '+p.color+' '+extra+'">'+esc(p.initials)+'</div>'}
function button(action,name,label,extra=''){return '<button type="button" class="icon-button" data-action="'+action+'" aria-label="'+esc(label)+'" title="'+esc(label)+'" '+extra+'>'+icon(name)+'</button>'}
function roomOrder(room){return state.orders.find(o=>o.id===room.orderId)}
function stageBadge(o){return '<span class="badge '+(STAGES.indexOf(o.stage)>=4?'green':o.stage==='Печать'?'orange':'')+'">'+esc(o.stage)+'</span>'}
function roomButton(r){const last=state.messages.filter(m=>m.roomId===r.id).at(-1);const o=roomOrder(r);return '<button class="room '+(state.active===r.id&&view==='chat'?'active':'')+'" data-room="'+esc(r.id)+'"><span class="room-symbol '+(r.kind==='order'?'order-symbol':'')+'">'+(r.kind==='order'?icon('orders'):'#')+'</span><span class="room-content"><span class="room-title">'+esc(o?o.number:r.name)+'</span><span class="room-preview">'+esc(o?r.name:(last?.text||r.description||'Новый чат'))+'</span></span>'+(r.unread?'<span class="room-unread">'+r.unread+'</span>':'')+'</button>'}
function renderRoomList(){const q=query.trim().toLocaleLowerCase('ru');const rooms=state.rooms.filter(r=>!q||(r.name+' '+(roomOrder(r)?.number||'')).toLocaleLowerCase('ru').includes(q)||state.messages.some(m=>m.roomId===r.id&&m.text.toLocaleLowerCase('ru').includes(q)));return '<div class="section-label">Команда <span>'+rooms.filter(r=>r.kind==='channel').length+'</span></div>'+rooms.filter(r=>r.kind==='channel').map(roomButton).join('')+'<div class="section-label chat-section">Чаты заказов <span>'+rooms.filter(r=>r.kind==='order').length+'</span></div>'+rooms.filter(r=>r.kind==='order').map(roomButton).join('')+(!rooms.length?'<div class="no-results">Чаты и сообщения не найдены</div>':'')}
function render(){const chat=view==='chat';$('#app').innerHTML='<div class="shell '+(showContext?'context-open ':'')+(navOpen?'nav-open':'')+'"><div class="prototype"><span class="dot"></span><b>Прототип</b><span>·</span><span>Переписка сохраняется в этом браузере</span><span class="proto-extra">· Демонстрационные заказы</span></div><nav class="rail" aria-label="Разделы"><div class="brand" title="Полицентр"><i></i><i></i><i></i><i></i></div><button class="rail-btn '+(chat?'active':'')+'" data-view="chat" title="Сообщения" aria-label="Сообщения">'+icon('chat')+'</button><button class="rail-btn '+(view==='orders'?'active':'')+'" data-view="orders" title="Заказы" aria-label="Заказы">'+icon('orders')+'</button><div class="rail-bottom"><button class="rail-btn '+(view==='settings'?'active':'')+'" data-view="settings" title="Настройки" aria-label="Настройки">'+icon('settings')+'</button>'+avatar('me')+'</div></nav><aside class="sidebar"><div class="workspace"><div><strong>Полицентр</strong><small>WORKSPACE</small></div><span class="down">'+icon('down')+'</span></div><div class="sidebar-heading"><h1>Сообщения</h1><button class="new-button" data-action="new-chat" aria-label="Новый чат" title="Новый чат">'+icon('edit')+'</button></div><div class="searchbox">'+icon('search')+'<input id="room-search" value="'+esc(query)+'" placeholder="Поиск чатов и сообщений" aria-label="Поиск чатов и сообщений"></div><div class="sidebar-scroll" id="room-list">'+renderRoomList()+'</div><div class="sidebar-footer">'+avatar('me')+'<div><b>Михаил</b><small>Роль в демо: '+(state.role==='manager'?'менеджер':'исполнитель')+'</small></div><button class="icon-button" style="margin-left:auto" data-view="settings" aria-label="Настройки роли">'+icon('settings')+'</button><button class="icon-button mobile-menu" data-view="orders" aria-label="Список заказов">'+icon('orders')+'</button></div></aside>'+(chat?renderChat()+renderContext():view==='orders'?renderOrders():renderSettings())+'</div>';
if(chat){$('#message-input').value=drafts.get(state.active)||'';$('#attach-input').addEventListener('change',handleFiles);scrollBottom()}
}
function renderChat(){const room=activeRoom();const o=roomOrder(room);return '<main class="chat-main"><header class="chat-header"><button class="icon-button mobile-menu" data-action="toggle-nav" aria-label="Открыть чаты">'+icon('menu')+'</button><span class="room-symbol">'+(o?icon('orders'):'#')+'</span><div><h2>'+esc(o?o.number+' · '+room.name:room.name)+'</h2><div class="chat-subtitle">'+(o?stageBadge(o):'<span class="dot"></span>Рабочий чат')+'<span>·</span><span>Демо-команда</span></div></div><div class="header-actions">'+button('toggle-search','search','Поиск в чате')+button('toggle-context','info',o?'Карточка заказа':'Информация о чате')+'</div></header>'+(room.pinned?'<div class="pinned">'+icon('pin')+'<div><b>Закреплено</b><br>'+esc(room.pinned)+'</div><button data-action="dismiss-pin" aria-label="Скрыть закреплённое">×</button></div>':'')+(showSearch?'<div class="chat-search"><input id="chat-search" value="'+esc(chatQuery)+'" placeholder="Найти сообщение в этом чате" aria-label="Поиск в текущем чате">'+button('close-search','close','Закрыть поиск')+'</div>':'')+'<div class="messages" id="messages" role="log" aria-label="Сообщения чата" aria-live="polite">'+renderMessages()+'</div><div class="composer-area"><form id="composer-form" class="composer">'+renderComposerExtras()+'<textarea id="message-input" maxlength="8000" rows="2" placeholder="Сообщение в '+esc(o?o.number:'#'+room.name)+'…" aria-label="Текст сообщения"></textarea><div class="composer-tools">'+button('attach','attach','Добавить файл')+button('emoji','smile','Добавить эмодзи')+'<span class="composer-hint">Enter — отправить · Shift + Enter — новая строка</span><button type="submit" class="send" aria-label="Отправить сообщение" title="Отправить">'+icon('send')+'</button></div><input id="attach-input" type="file" hidden multiple></form><div class="composer-footnote"><span>Договорённости — рядом с работой</span><span>Полицентр Workspace</span></div></div></main>'}
function renderComposerExtras(){const reply=state.messages.find(m=>m.id===replyTo);return (reply?'<div class="reply-preview">'+icon('reply')+'<span>Ответ '+esc(people[reply.author]?.name||'участнику')+': '+esc(reply.text||'Вложение')+'</span><button type="button" data-action="cancel-reply" aria-label="Отменить ответ">×</button></div>':'')+(pending.length?'<div class="pending-files">'+pending.map((f,i)=>'<div class="pending-file"><span>'+esc(f.name)+' · '+formatBytes(f.size)+'</span><button type="button" data-remove-file="'+i+'" aria-label="Убрать файл">×</button></div>').join('')+'</div>':'')+(emojiOpen?'<div class="emoji-picker">'+['👍','✅','👋','🙏','🎨','🖨️'].map(e=>'<button type="button" data-emoji="'+e+'" aria-label="Добавить '+e+'">'+e+'</button>').join('')+'</div>':'')}
function renderMessages(){const rows=state.messages.filter(m=>m.roomId===state.active&&(!chatQuery||m.text.toLocaleLowerCase('ru').includes(chatQuery.toLocaleLowerCase('ru'))));if(!rows.length)return '<div class="empty">'+(chatQuery?'Сообщений с таким текстом нет':'Начните обсуждение<br>Напишите первое сообщение в этом чате')+'</div>';let previousDay='';return rows.map(m=>{const p=people[m.author]||people.me;const date=new Date(m.time);const dateKey=date.toLocaleDateString('ru-RU',{timeZone:'Asia/Vladivostok'});let divider='';if(dateKey!==previousDay){divider='<div class="day-divider">'+esc(dateKey===new Date().toLocaleDateString('ru-RU',{timeZone:'Asia/Vladivostok'})?'Сегодня':dateKey)+'</div>';previousDay=dateKey}const reply=state.messages.find(x=>x.id===m.replyTo);const order=state.orders.find(o=>o.id===m.orderRef);return divider+'<article class="message '+(m.author==='me'?'own':'')+'">'+avatar(m.author)+'<div class="message-body"><div class="message-meta"><b>'+esc(p.name)+'</b>'+(m.author==='me'?'<span class="person-role">Вы</span>':'<span class="person-role">'+esc(p.role)+'</span>')+'<time datetime="'+esc(m.time)+'">'+date.toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit',timeZone:'Asia/Vladivostok'})+'</time></div>'+(reply?'<div class="reply-quote">'+esc(people[reply.author]?.name)+': '+esc(reply.text||'Вложение')+'</div>':'')+(m.text?'<div class="message-text">'+esc(m.text)+'</div>':'')+(m.attachmentDemo?'<button type="button" class="attachment" data-action="download-guide"><span class="file-icon">'+icon('file')+'</span><span><strong>Памятка по передаче макетов.txt</strong><small>Демонстрационный файл · TXT</small></span>'+icon('download')+'</button>':'')+(m.attachments||[]).map(f=>'<button type="button" class="attachment" data-download-message="'+esc(m.id)+'" data-file-id="'+esc(f.id)+'"><span class="file-icon">'+icon('file')+'</span><span><strong>'+esc(f.name)+'</strong><small>'+formatBytes(f.size)+' · локальный файл</small></span>'+icon('download')+'</button>').join('')+(order?'<button class="order-message" data-room="'+esc(order.roomId)+'"><span class="room-symbol">'+icon('orders')+'</span><span><strong>'+esc(order.number)+' · '+esc(order.title)+'</strong><small>'+esc(order.quantity)+' · '+esc(order.stage)+'</small></span><span class="arrow">'+icon('arrow')+'</span></button>':'')+((m.reactions||[]).length?'<button class="reaction '+(m.reactions.includes('me')?'selected':'')+'" data-react="'+esc(m.id)+'" aria-label="Реакция нравится">👍 '+m.reactions.length+'</button>':'')+'</div><div class="message-actions"><button class="icon-button" data-react="'+esc(m.id)+'" aria-label="Нравится">'+icon('smile')+'</button><button class="icon-button" data-reply="'+esc(m.id)+'" aria-label="Ответить">'+icon('reply')+'</button></div></article>'}).join('')}
function renderContext(){const room=activeRoom(),o=roomOrder(room);return '<aside class="context"><div class="context-heading">'+(o?'Карточка заказа':'О чате')+button('toggle-context','close','Скрыть панель')+'</div><div class="context-body">'+(o?renderOrderContext(o):'<div class="context-label">Информация</div><div class="context-icon">'+icon('chat')+'</div><h3>'+esc(room.name)+'</h3><p class="context-desc">'+esc(room.description||'Рабочее обсуждение команды. Все договорённости и решения сохраняем здесь.')+'</p><div class="mini-list"><div class="mini-row"><span>Тип чата</span><span>Командный</span></div><div class="mini-row"><span>Участники</span><span>Демо-команда</span></div><div class="mini-row"><span>Сообщения</span><span>'+state.messages.filter(m=>m.roomId===room.id).length+'</span></div></div>')+'<div class="context-divider"></div><div class="context-label">Команда <span style="float:right">4</span></div>'+Object.entries(people).map(([id,p])=>'<div class="member">'+avatar(id)+'<div><strong>'+esc(p.name)+'</strong><small>'+esc(id==='me'?(state.role==='manager'?'Менеджер · демо':'Исполнитель · демо'):p.role)+'</small></div>'+(id==='me'?'<span class="you">Вы</span>':'')+'</div>').join('')+'<div class="context-divider"></div><div class="info-note">'+(o?'Данные заказа демонстрационные. Access и Excel подключим через импорт.':'Обсуждайте детали заказа в его чате — переписка и этапы будут рядом.')+'</div></div></aside>'}
function renderOrderContext(o){return '<div class="context-label">'+esc(o.number)+'</div><div class="context-icon">'+icon('orders')+'</div><h3>'+esc(o.title)+'</h3><p class="context-desc">'+esc(o.customer)+'</p><div class="mini-list"><div class="mini-row"><span>Тираж</span><span>'+esc(o.quantity||'Не указан')+'</span></div><div class="mini-row"><span>Бумага</span><span>'+esc(o.paper||'Не указана')+'</span></div><div class="mini-row"><span>Формат</span><span>'+esc(o.format||'Не указан')+'</span></div><div class="mini-row"><span>Срок</span><span>'+esc(o.due||'Не указан')+'</span></div><div class="mini-row"><span>Оплата</span><span>'+esc(o.payment)+'</span></div></div><div class="context-divider"></div><label for="order-stage">Этап производства</label><div class="progress">'+STAGES.map((_,i)=>'<i class="'+(i<=STAGES.indexOf(o.stage)?'done':'')+'"></i>').join('')+'</div><select id="order-stage" data-order-stage="'+esc(o.id)+'" class="stage-control" '+(!canEditStage(state.role,o)?'disabled':'')+'>'+STAGES.map(s=>'<option '+(o.stage===s?'selected':'')+'>'+esc(s)+'</option>').join('')+'</select><div class="stage-note">'+(canEditStage(state.role,o)?'Вы можете обновить этап этого заказа.':'Этап меняет назначенный исполнитель или менеджер.')+'</div>'+(state.role==='manager'?'<div style="margin-top:17px"><label for="order-payment">Подтверждение оплаты · демо</label><select id="order-payment" data-order-payment="'+esc(o.id)+'" class="stage-control">'+PAYMENTS.map(p=>'<option '+(p===o.payment?'selected':'')+'>'+esc(p)+'</option>').join('')+'</select></div>':'')+'<button class="order-cta" data-view="orders">Все заказы '+icon('arrow')+'</button>'}
function renderOrders(){const orders=state.orders;return '<main class="orders-main"><div class="orders-top"><div><h2><button class="icon-button mobile-menu" data-action="toggle-nav" aria-label="Открыть чаты">'+icon('menu')+'</button>Заказы в работе</h2><p>Обсуждения, исполнители и этапы в одном месте</p></div><button class="primary" data-action="new-chat">+ Новый заказ</button></div><div class="order-stats"><div class="stat"><b>'+orders.filter(o=>o.stage!=='Выдан').length+'</b><span>В работе</span></div><div class="stat"><b>'+orders.filter(o=>o.executorId==='me').length+'</b><span>Мои заказы</span></div><div class="stat"><b>'+orders.filter(o=>o.stage==='Готов к выдаче').length+'</b><span>Готовы к выдаче</span></div></div><table class="orders-table"><thead><tr><th>Заказ</th><th>Этап</th><th>Срок</th><th>Обсуждение</th></tr></thead><tbody>'+orders.map(o=>'<tr data-room="'+esc(o.roomId)+'"><td><span class="order-code">'+esc(o.number)+'</span><strong>'+esc(o.title)+'</strong><small>'+esc(o.quantity||'Тираж не указан')+'</small></td><td>'+stageBadge(o)+'</td><td>'+esc(o.due||'Не указан')+'</td><td><button class="icon-button" data-room="'+esc(o.roomId)+'" aria-label="Открыть чат заказа '+esc(o.number)+'">'+icon('chat')+'</button></td></tr>').join('')+'</tbody></table><p class="muted" style="margin-top:22px">Демонстрационные данные. Импорт Access и Excel добавим отдельно.</p></main>'}
function renderSettings(){return '<main class="settings-panel"><h2><button class="icon-button mobile-menu" data-action="toggle-nav" aria-label="Открыть чаты">'+icon('menu')+'</button>Настройки прототипа</h2><div class="settings-card"><h3>Роль для проверки сценариев</h3><p>Переключение демонстрирует интерфейс исполнителя и менеджера. В рабочей версии роль будет назначаться на сервере после входа сотрудника.</p><label for="role-select">Текущая роль</label><select id="role-select"><option value="executor" '+(state.role==='executor'?'selected':'')+'>Исполнитель (демо)</option><option value="manager" '+(state.role==='manager'?'selected':'')+'>Менеджер (демо)</option></select></div><div class="settings-card"><h3>Переписка в этом браузере</h3><p>Сообщения, реакции, вложения и этапы сохраняются локально. Другие сотрудники и устройства их пока не получают. Следующий этап — общая серверная история, вход сотрудников и обновления в реальном времени.</p><button class="primary" data-action="export">Экспортировать демо-переписку</button></div><div class="settings-card"><h3>Интеграция базы — следующим этапом</h3><p>Обсуждение связано с внутренним ID заказа. Для Access, Excel и других источников предусмотрим отдельные адаптеры импорта. Существующий MDB для прототипа не используется.</p><button class="order-cta" data-view="chat">Вернуться к переписке</button></div></main>'}
function scrollBottom(){requestAnimationFrame(()=>{const el=$('#messages');if(el&&!chatQuery)el.scrollTop=el.scrollHeight})}
function refreshComposer(){drafts.set(state.active,$('#message-input')?.value||drafts.get(state.active)||'');const text=drafts.get(state.active)||'';render();$('#message-input').value=text}
function download(name,body,type){const blob=new Blob([body],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000)}
function openRoom(id){if(!state.rooms.some(r=>r.id===id))return;if($('#message-input'))drafts.set(state.active,$('#message-input').value);state.active=id;activeRoom().unread=0;view='chat';replyTo=null;pending=[];emojiOpen=false;chatQuery='';showSearch=false;navOpen=false;persist();render()}
function addSystemText(roomId,text){state.messages.push({id:crypto.randomUUID(),roomId,author:'me',text,time:new Date().toISOString(),reactions:[]})}
async function handleFiles(event){const selection=[...event.target.files];if(selection.length+pending.length>3){toast('Можно приложить до 3 файлов к сообщению');return}let total=pending.reduce((s,f)=>s+f.size,0);for(const file of selection){if(file.size>1048576||total+file.size>2*1048576){toast('Для прототипа: файл до 1 МБ, вложения до 2 МБ на сообщение');continue}const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)}).catch(()=>null);if(!data){toast('Не удалось прочитать файл');continue}pending.push({id:crypto.randomUUID(),name:file.name,size:file.size,type:file.type,data});total+=file.size}refreshComposer()}
document.addEventListener('input',event=>{if(event.target.id==='room-search'){query=event.target.value;$('#room-list').innerHTML=renderRoomList()}if(event.target.id==='chat-search'){chatQuery=event.target.value;$('#messages').innerHTML=renderMessages()}if(event.target.id==='message-input')drafts.set(state.active,event.target.value)});
document.addEventListener('keydown',event=>{if(event.target.id==='message-input'&&event.key==='Enter'&&!event.shiftKey&&!event.isComposing){event.preventDefault();$('#composer-form').requestSubmit()}if(event.key==='Escape'){showContext=false;navOpen=false;if(showSearch){showSearch=false;chatQuery=''}if(view==='chat')refreshComposer();else render()}});
document.addEventListener('submit',event=>{if(event.target.id==='composer-form'){event.preventDefault();try{const text=validateMessage($('#message-input').value,pending);const message={id:crypto.randomUUID(),roomId:state.active,author:'me',text,time:new Date().toISOString(),replyTo,attachments:[...pending],reactions:[]};const previous=state.messages;state.messages=[...state.messages,message];if(!persist()){state.messages=previous;return}drafts.delete(state.active);replyTo=null;pending=[];emojiOpen=false;chatQuery='';render();$('#message-input').focus()}catch(error){toast(error.message)}}if(event.target.id==='new-form'){event.preventDefault();const fields=new FormData(event.target),title=String(fields.get('title')||'').trim(),number=String(fields.get('number')||'').trim();if(!title){toast('Введите название чата');return}const roomId=crypto.randomUUID();let orderId;if(number){if(state.orders.some(o=>o.number.toLowerCase()===number.toLowerCase())){toast('Заказ с таким номером уже существует');return}orderId=crypto.randomUUID();state.orders.push({id:orderId,roomId,number,title,customer:'Новый демонстрационный заказ',quantity:'',paper:'',format:'',due:'',stage:'Новый',payment:'Не подтверждена',executorId:'me'})}state.rooms.push({id:roomId,name:title,kind:orderId?'order':'channel',orderId,unread:0,description:'Рабочий чат команды'});persist();$('#new-dialog').close();event.target.reset();openRoom(roomId);toast(orderId?'Заказ и чат созданы':'Чат создан')}});
document.addEventListener('change',event=>{try{if(event.target.id==='role-select'){state.role=event.target.value;persist();render();toast('Демонстрационная роль изменена')}if(event.target.dataset.orderStage){const i=state.orders.findIndex(o=>o.id===event.target.dataset.orderStage);state.orders[i]=setOrderStage(state.orders[i],event.target.value,state.role);addSystemText(state.orders[i].roomId,'Этап заказа изменён: '+event.target.value);persist();render();toast('Этап обновлён')}if(event.target.dataset.orderPayment){const i=state.orders.findIndex(o=>o.id===event.target.dataset.orderPayment);state.orders[i]=setPayment(state.orders[i],event.target.value,state.role);addSystemText(state.orders[i].roomId,'Статус оплаты подтверждён в демо: '+event.target.value);persist();render();toast('Демонстрационный статус оплаты обновлён')}}catch(error){toast(error.message);render()}});
document.addEventListener('click',event=>{const button=event.target.closest('button,[data-room]');if(!button)return;if(button.dataset.room){openRoom(button.dataset.room);return}if(button.dataset.view){if($('#message-input'))drafts.set(state.active,$('#message-input').value);view=button.dataset.view;navOpen=false;render();return}if(button.dataset.reply){replyTo=button.dataset.reply;refreshComposer();$('#message-input').focus();return}if(button.dataset.react){const m=state.messages.find(m=>m.id===button.dataset.react);if(m){m.reactions=m.reactions||[];m.reactions=m.reactions.includes('me')?m.reactions.filter(x=>x!=='me'):[...m.reactions,'me'];persist();const top=$('#messages').scrollTop;$('#messages').innerHTML=renderMessages();$('#messages').scrollTop=top}return}if(button.dataset.removeFile!==undefined){pending.splice(Number(button.dataset.removeFile),1);refreshComposer();return}if(button.dataset.emoji){const input=$('#message-input');input.value+=button.dataset.emoji;drafts.set(state.active,input.value);emojiOpen=false;refreshComposer();$('#message-input').focus();return}if(button.dataset.downloadMessage){const file=state.messages.find(m=>m.id===button.dataset.downloadMessage)?.attachments?.find(f=>f.id===button.dataset.fileId);if(file&&/^data:[^,]*;base64,[A-Za-z0-9+/=\r\n]*$/.test(file.data)){const a=document.createElement('a');a.href=file.data;a.download=file.name;a.click()}else toast('Файл недоступен');return}switch(button.dataset.action){case'new-chat':$('#new-dialog').showModal();break;case'close-dialog':$('#new-dialog').close();break;case'toggle-nav':navOpen=!navOpen;render();break;case'toggle-context':showContext=!showContext;refreshComposer();break;case'toggle-search':showSearch=!showSearch;if(!showSearch)chatQuery='';refreshComposer();if(showSearch)$('#chat-search').focus();break;case'close-search':showSearch=false;chatQuery='';refreshComposer();break;case'dismiss-pin':delete activeRoom().pinned;persist();refreshComposer();break;case'cancel-reply':replyTo=null;refreshComposer();break;case'attach':$('#attach-input').click();break;case'emoji':emojiOpen=!emojiOpen;refreshComposer();break;case'export':download('policentr-demo-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify(state,null,2),'application/json');toast('Демо-переписка экспортирована');break;case'download-guide':download('Памятка по передаче макетов.txt','Демонстрационная памятка Полицентр\n\n1. Проверьте размер и вылеты.\n2. Проверьте шрифты и изображения.\n3. Уточните цветовую модель и профиль у печатника.\n4. Согласуйте макет в чате заказа.\n\nЭто демонстрационный файл, а не утверждённый производственный регламент.','text/plain;charset=utf-8');break;}});
window.addEventListener('storage',event=>{if(event.key!==storageKey||!event.newValue)return;try{const next=JSON.parse(event.newValue);if(next.version===1&&Array.isArray(next.messages)&&Array.isArray(next.rooms)&&Array.isArray(next.orders)){state=next;render()}}catch{}});
render();
